-- indice real de producao: CREATE UNIQUE INDEX ux_casos_uma_ficha_aberta_por_aluno ON public.casos USING btree (aluno_id) WHERE ((aluno_id IS NOT NULL) AND (NOT COALESCE(encerrado_operacional, false)))
CREATE UNIQUE INDEX ux_casos_uma_ficha_aberta_por_aluno ON public.casos USING btree (aluno_id) WHERE ((aluno_id IS NOT NULL) AND (NOT COALESCE(encerrado_operacional, false)));
